import{d as c,C as t,o as p,c as u,j as a,a as o,E as s,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第七十二章","description":"从民不畏威读任威的反效，分列居生与不厌的句面读法及王注，辨自知自爱与自见自贵。","frontmatter":{"title":"道德经第七十二章","description":"从民不畏威读任威的反效，分列居生与不厌的句面读法及王注，辨自知自爱与自见自贵。","category":"guide","aliases":["道德经第七十二章","老子第七十二章","dao de jing chapter 72"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-72.md","filePath":"daoism/dao-de-jing/chapter-72.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-72.md"},_=c({...m,setup(x){const r=[{id:"authority-and-its-reversal",label:"民不畏威，则大威至",showLabel:!0,sentences:[["民不畏",{text:"威",glossary:"wei"},"，则",{text:"大威",glossary:"dawei"},"至。"]],note:["【白话】百姓不再畏惧威压时，更大的威势或灾变就会来到。王弼将这个大威具体解释为上下溃乱之后，天的诛责将至。","【王弼注择要】「民不能堪其威，则上下大溃矣。天诛将至」，由此说明何以说民不畏威则大威至。","【读法】注的因果不是民不怕就该施更大的恐吓，而是任威使民不堪，终至原有威势也难以约束。天诛仍是所据注的古代观念。"]},{id:"dwelling-and-livelihood",label:"无狎其所居，无厌其所生",showLabel:!0,sentences:[["无",{text:"狎",glossary:"xia"},"其所居，无",{text:"厌",glossary:"yan-oppress"},"其所生。"]],note:["【白话】先按句面的一种读法：不要侵扰百姓的居处，不要压迫他们的生计。狎取轻扰、侵迫，厌可从压迫理解。","【王弼注择要】「清静无为，谓之居；谦后不盈，谓之生。」所据注另把居与生放回清静、谦后，继而批评离其清静、任其威权。","【读法】两种解释的着眼点不同：前者由民的居处生计读，王注由在上者安处清静、持守谦后读。本页并列交代，不把王注当成前一种白话的逐字证明。"]},{id:"not-oppressing-not-being-rejected",label:"夫唯不厌，是以不厌",showLabel:!0,sentences:[["夫唯不",{text:"厌",glossary:"yan-oppress"},"，是以不",{text:"厌",glossary:"yan-dislike"},"。"]],note:["【白话】承前面的句面读法：正因为不压迫百姓，所以才不被百姓厌弃。前一厌与后一厌，在这一读法中分别作压迫与厌弃。","【王弼注择要】前一不厌下注「不自厌也」，继而说「不自厌，是以天下莫之厌」。注将前者收在自己如何持守，后者说天下不厌弃他。","【读法】依王注上下文，不自厌可连不厌舍清静谦后的自处来理解；不强行套成现代自我厌恶的心理描述。白话与所据注的取径在此仍分别标明。"]},{id:"self-knowledge-without-display",label:"自知不自见",showLabel:!0,sentences:[["是以圣人自知不自",{text:"见",glossary:"xian"},"，"]],note:["【白话】因此，圣人能认识自己，却不把自己的所知拿来炫示。他不靠展示自己高明来对人施加威势。","【王弼注择要】「不自见其所知，以耀光行威也。」注着重不以炫示所知来耀光行威。","【读法】见读 xiàn，取显露、表现义。自知与自见不是要二选一的知识多少，而是认识自己之后，是否急于借此抬高自己。"]},{id:"self-care-without-exaltation",label:"自爱不自贵",showLabel:!0,sentences:[["自爱不",{text:"自贵",glossary:"zigui"},"。"]],note:["【白话】圣人爱护、珍重自己，却不把自己抬到尊贵的高位。不自贵没有取消自爱，而是给自爱保留谦后的尺度。","【王弼注择要】「自贵则物狎厌居生」，注以自贵会扰乱居生来接回前文，对自己如何居处与行威作出警戒。","【读法】此处注语简约，可结合清静、谦后与任威的前注理解，不将物狎厌居生拆作已经逐字定解的现代译句。"]},{id:"choosing-what-to-retain",label:"故去彼取此",showLabel:!0,sentences:[["故",{text:"去",glossary:"qu-remove"},"彼",{text:"取",glossary:"qu-choose"},"此。"]],note:["【白话】所以，去掉自见、自贵，取自知、自爱。彼与此都回指前面的对照，末句收束的是在这些做法之间如何选择。","【读法】去彼不等于否定一切展示与说明，取此也不等于只顾自己。读回本章，关键仍是不以炫耀、抬尊和威压代替清静谦后的自处。"]}],i=[{id:"wei",term:"威",sense:1},{id:"dawei",term:"大威",sense:1},{id:"xia",term:"狎",sense:1},{id:"yan-oppress",term:"厌",sense:3},{id:"yan-dislike",term:"厌",sense:2},{id:"xian",term:"见",sense:1},{id:"zigui",term:"自贵",sense:1},{id:"qu-remove",term:"去",sense:1},{id:"qu-choose",term:"取",sense:3}];return(g,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return p(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十二章",tabindex:"-1"},[o("道德经第七十二章 "),a("a",{class:"header-anchor",href:"#道德经第七十二章","aria-label":'Permalink to "道德经第七十二章"'},"​")],-1)),s(n,{title:"依恃威势，为什么反会使威势失效",summary:"本章由民不畏威说起，把警戒转向居上者怎样对待民、怎样安顿自己。无狎无厌可先从不扰居处、不压生计读；王弼另以清静无为为居、谦后不盈为生。结尾落在自知自爱，去掉炫示所知和自抬尊贵。",points:[{label:"先读",text:"民不畏威之后紧接大威至，先看威势为何可能反成灾变。"},{label:"再辨",text:"居处生计的句面读法，与王注清静谦后的解释分列；两处不厌也要辨明所指。"},{label:"后看",text:"自知不自见、自爱不自贵成对阅读，去彼取此回收这两组选择。"}],hint:"狎读 xiá，厌读 yàn；无厌其所生可从厌通压读。不自见的见读 xiàn，表示显露、炫示。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:r,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"民不畏威，则大威至。",tone:"任威的反效",guide:"王注从民不堪威、上下大溃解释，不作为加码威吓的依据。"},{text:"无狎其所居，无厌其所生。",tone:"两条解释分别看",guide:"先读不扰居生，再辨王注以清静、谦后说居与生。"},{text:"是以圣人自知不自见，自爱不自贵。",tone:"保留自知与自爱",guide:"去掉的是借所知行威、抬尊自己，不是把自身价值一并否定。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:i}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-大威至是在鼓励更大的威吓吗" tabindex="-1">象：大威至是在鼓励更大的威吓吗？ <a class="header-anchor" href="#象-大威至是在鼓励更大的威吓吗" aria-label="Permalink to &quot;象：大威至是在鼓励更大的威吓吗？&quot;">​</a></h3><p>依王注，民不堪威而上下大溃，天诛因而将至。所警戒的是治理者依恃威权造成的反效，不能把大威抽出，当成以恐吓解决不服从的命令。</p><h3 id="理-为什么居生的白话和王注要分开说" tabindex="-1">理：为什么居生的白话和王注要分开说？ <a class="header-anchor" href="#理-为什么居生的白话和王注要分开说" aria-label="Permalink to &quot;理：为什么居生的白话和王注要分开说？&quot;">​</a></h3><p>句面可由百姓的居处、生计理解，王注则明列清静无为谓之居、谦后不盈谓之生。两者可以相参，但着眼点不同；标明取径，才能让读者分清哪部分是原注、哪部分是本站释读。</p><h3 id="用-自知自爱怎样不变成自见自贵" tabindex="-1">用：自知自爱怎样不变成自见自贵？ <a class="header-anchor" href="#用-自知自爱怎样不变成自见自贵" aria-label="Permalink to &quot;用：自知自爱怎样不变成自见自贵？&quot;">​</a></h3><p>可以清楚说明自己的判断和需要，同时给别人保留核实、质疑与不同选择的空间。不必贬低自己，也不借自己的地位或知识使他人难以表达。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>检查威势已经遮住了什么。</strong> 当别人不愿回应时，先看要求是否过重、表达渠道是否有效、提出异议会承担什么代价。比继续加大声量，更能看清问题为何积累。</p><p><strong>把自重落实为对等的边界。</strong> 说明自己的职责和需要，也承认别人的职责和需要。自爱因此可以与谦下共存，而不必靠让别人显得低一等来成立。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把知识或位置变成了使人难以反驳的威势？怎样保留自知、自爱，同时减少别人实际承受的压迫？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 008a–008b 电子录文核对。</li><li>无狎无厌先列不扰居处、不压生计的句面读法，再列所据注清静无为谓之居、谦后不盈谓之生；不将两种取径合成一条无歧义的译文。</li><li>夫唯不厌、是以不厌先按不压迫与不被厌弃分义，再明确王注前者不自厌、后者天下莫之厌的读法，字词浮层服务前一白话取径。</li><li>自见读 xiàn，依不自见其所知以耀光行威也解释；自贵后注自贵则物狎厌居生保留录文字面，不擅补字或改写后冒作原注。</li><li>王注天诛、任威的古代政治观念与现代协作启发分层；古注节引转简体并加标点，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，008a–008b</a>。</p>',15))])}}});export{y as __pageData,_ as default};
